function padArrayStart(arr, n, padValue = 0) {
  // Calculate how many padding elements are needed.
  const paddingNeeded = Math.max(0, n - arr.length);

  // Create a new array filled with the padValue.
  const paddingArray = Array(paddingNeeded).fill(padValue);

  // Concatenate the padding array with the original array.
  return paddingArray.concat(arr);
}

