function findConsecutiveGroups(arr) {
    if (arr.length === 0) return [];

    // Sort the array
    arr.sort((a, b) => a - b);

    let groups = [];
    let currentGroup = [arr[0]];
    for (let i = 1; i < arr.length; i++) {
        if (arr[i] === arr[i - 1] + 1) {
            currentGroup.push(arr[i]);
        } else {
            if (currentGroup.length > 0) {
                groups.push([...currentGroup]);
            }
            currentGroup = [arr[i]];
        }
    }
    node.warn(currentGroup)

    // Add the last group if it's valid
    if (currentGroup.length > 0) {
        groups.push(currentGroup);
    }

    return groups;
}


