        firstSeen: 0,
        lastReset: 0,
        retries: 0,
        emailSent: false
    });

    return [null, null, null];
}

// -------------------------------------------------
// ✅ FIRST DETECTION
// -------------------------------------------------
if (!state.firstSeen) {
    state.firstSeen = now;
    context.set("state", state);
    return [null, null, null];
}

// -------------------------------------------------
// ✅ WAIT 90 sec
// -------------------------------------------------
if ((now - state.firstSeen) < 90000) {
    return [null, null, null];
}

// -------------------------------------------------
// ✅ MAX RETRIES → SEND EMAIL ONCE
// -------------------------------------------------
if (state.retries >= 3) {

    if (!state.emailSent) {

        state.emailSent = true;
