// -------------------------------------------------
if ((now - state.lastReset) < 60000) {
    return [null, null, null];
}

// -------------------------------------------------
// ✅ PERFORM RESET
// -------------------------------------------------
state.retries += 1;
state.lastReset = now;

context.set("state", state);

