let index = msg.payload?.index;

// ADD
if (action === "add") {
    zones.push({ zone_id:"", zone_name:"", editing:true });
}

// EDIT
if (action === "edit" && zones[index]) {
    zones[index].editing = true;
}

// SAVE
if (action === "save" && zones[index]) {

    let z = zones[index];

    if (!z.zone_id || !z.zone_name) {
        return {payload:{zones, error:"Missing fields", action:"save"}};
    }

    // Duplicate check
    let dup = zones.find((x,i)=> x.zone_id === z.zone_id && i !== index);
    if (dup) {
        return {payload:{zones, error:"Duplicate Zone ID", action:"save"}};
    }

    z.editing = false;

    global.set("zone_master", zones);
    return {payload:{zones, success:"Zone saved", action:"save"}};
}

// DELETE
if (action === "delete" && zones[index]) {
    zones.splice(index,1);
    global.set("zone_master", zones);
}

// OUTPUT
msg.payload = { zones };
return msg;

