let selectedSlave = flow.get("selectedSlave");
if (!selectedSlave) {
    msg.payload = { labels: [], datasets: [] };
    return msg;
}

let dailyCount = {};

rows.forEach(r => {
    if (!r || !r.Status || !r.Slave || !r.Date) return;
    if (selectedSlave !== "All" && String(r.Slave).trim() !== selectedSlave) return;

    let status = String(r.Status).trim().toLowerCase();
    if (status !== "disconnected" && status !== "disonnected") return;

    let date = String(r.Date).trim();
    dailyCount[date] = (dailyCount[date] || 0) + 1;
});

// Sort dates
let dates = Object.keys(dailyCount).sort((a, b) => {
    const [da, ma, ya] = a.split("-").map(Number);
    const [db, mb, yb] = b.split("-").map(Number);
    // @ts-ignore
    return (new Date(ya, ma-1, da) - new Date(yb, mb-1, db));
});

msg.payload = {
    labels: dates,
    datasets: [{
        label: `Daily Disconnections – ${selectedSlave}`,
        data: dates.map(d => dailyCount[d]),
        backgroundColor: "#e67e22"
    }]
};

return msg;

/**
 * PURPOSE:
 * - Build dynamic Slave dropdown
 * - Include "All" option
 * - Include ONLY slaves that have at least one Disconnected entry
 * - Sort slaves in ASCENDING NUMERIC order (Slave 2 < Slave 10 < Slave 29)
 * - Uses msg.options (Node-RED Dashboard standard)
 */

let rows = msg.payload;

// ---------- SAFETY ----------
if (!Array.isArray(rows)) {
    node.warn("CSV payload is not an array");
    msg.options = ["All"];
    return msg;
}

// Collect slaves with disconnections
let slaveSet = new Set();

rows.forEach(r => {
    if (!r || !r.Status || !r.Slave) return;

    let status = String(r.Status).trim().toLowerCase();

    if (status === "disconnected" || status === "disonnected") {
        let slave = String(r.Slave).trim();
        if (slave) slaveSet.add(slave);
    }
});

// ---------- SORT NUMERICALLY ----------
let sortedSlaves = Array.from(slaveSet).sort((a, b) => {
    // Extract numbers from "Slave XX"
    let na = parseInt(a.replace(/\D+/g, ""), 10);
    let nb = parseInt(b.replace(/\D+/g, ""), 10);

    // Fallback for safety
    if (isNaN(na)) return a.localeCompare(b);
    if (isNaN(nb)) return a.localeCompare(b);

    return na - nb;
});

// ---------- BUILD DROPDOWN OPTIONS ----------
msg.options = [
    "All",
    ...sortedSlaves
];

return msg;

